using EEMS.Modules.Results.Infrastructure;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;namespace EEMS.Modules.Results;public static class ResultsModule{public static IServiceCollection AddResultsModule(this IServiceCollection s,IConfiguration c){var x=c.GetConnectionString("EemsDatabase");if(string.IsNullOrWhiteSpace(x))throw new InvalidOperationException("ConnectionStrings:EemsDatabase is required.");s.AddDbContext<ResultsDbContext>(o=>o.UseNpgsql(x));return s;}}
